package com.acrenex.app.activities;
import android.database.Cursor;import android.os.Bundle;import android.widget.LinearLayout;import androidx.appcompat.app.AppCompatActivity;import com.acrenex.app.database.DatabaseManager;import com.acrenex.app.utils;
public class DisputeActivity extends AppCompatActivity{
 @Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=utils.screen(this,"Dispute & Legal Signals","Parcel-linked case status designed for controlled role-based access.");String u=getIntent().getStringExtra("ulpin");if(u==null)u="24-GJ-GN-0001-00001";DatabaseManager m=new DatabaseManager(this);Cursor c=m.getDatabase().rawQuery("SELECT case_number,forum,dispute_type,filing_date,status,next_hearing FROM disputes WHERE ulpin=?",new String[]{u});try{if(c.moveToFirst()){LinearLayout box=utils.column(this);utils.row(box,this,"Case",c.getString(0));utils.row(box,this,"Forum",c.getString(1));utils.row(box,this,"Type",c.getString(2));utils.row(box,this,"Filed",c.getString(3));utils.row(box,this,"Status",c.getString(4));utils.row(box,this,"Next hearing",c.getString(5));utils.addCard(root,box,this);}else root.addView(utils.text(this,"No dispute record in demo dataset.",14,utils.MUTED,false));}finally{c.close();}utils.setScreenContentView(this, root);}
}
